css:
td{border:0;border-bottom:1px solid rgba(0,0,0,.06);padding:20px 24px}
tr:last-child td{border-bottom:0}
th{border:0}
/* 列＝色帯にする版 */
.table{display:grid;grid-template-columns:repeat(6,1fr);gap:5px}
.col{background:#cfe6f7;border-radius:14px;padding:12px;display:grid;gap:12px}
/* 罫ゼロの定義リスト */
dl{display:grid;grid-template-columns:120px 1fr;row-gap:38px;border:0}
dt{color:#b79b5c;letter-spacing:.2em;font-size:12px}
dd{font-family:serif;letter-spacing:.06em}
